// 🏥 PROCESAR DATOS PARA ANÁLISIS DE RESPUESTAS
const webhookData = $input.all()[0].json;
console.log('🔍 Datos de respuestas:', JSON.stringify(webhookData, null, 2));

const inputData = webhookData.body || webhookData;

// ✅ VALIDAR DATOS REQUERIDOS
if (!inputData.paciente_id) {
  throw new Error('paciente_id es requerido');
}
if (!inputData.seguimiento_id) {
  throw new Error('seguimiento_id es requerido');
}
if (!inputData.respuestas_cuestionario) {
  throw new Error('respuestas_cuestionario son requeridas');
}

// 📊 EXTRAER DATOS ORGANIZADOS
const pacienteId = inputData.paciente_id;
const seguimientoId = inputData.seguimiento_id;
const respuestas = inputData.respuestas_cuestionario;

// 🏥 DATOS CLÍNICOS ACTUALIZADOS
const datosActualizados = inputData.datos_actualizados || {};
const triaje = datosActualizados.triaje || {};
const diagnosticos = datosActualizados.diagnosticos || [];
const prescripciones = datosActualizados.prescripciones || [];
const recomendaciones = datosActualizados.recomendaciones || [];

// 🎯 DATOS DE LA CAMPAÑA Y SEGUIMIENTOS ANTERIORES
const campanaDatos = inputData.campana_info || {};
const seguimientosAnteriores = inputData.seguimientos_anteriores || [];

// 🤖 DATOS DE FASTAPI (RIESGO CARDIOVASCULAR Y FACTORES)
const riesgoCardiovascular = inputData.riesgo_cardiovascular || {};
const factoresInfluyentes = inputData.factores_influyentes || {};
const priorizacion = inputData.priorizacion || {};

// 📝 ESTRUCTURAR INFORMACIÓN PARA ANÁLISIS
const datosAnalisis = {
  // Identificadores
  paciente_id: pacienteId,
  seguimiento_id: seguimientoId,

  // Respuestas del cuestionario actual
  respuestas_actuales: respuestas,

  // Estado clínico actual
  estado_clinico: {
    triaje: {
      presion_arterial: `${triaje.presion_sistolica || 'N/A'}/${triaje.presion_diastolica || 'N/A'}`,
      frecuencia_cardiaca: triaje.frecuencia_cardiaca || 'N/A',
      temperatura: triaje.temperatura || 'N/A',
      saturacion_oxigeno: triaje.saturacion_oxigeno || 'N/A'
    },
    diagnosticos_actuales: diagnosticos.map(d => ({ 
      codigo: d.codigo_cie10 || d.codigo,
      descripcion: d.descripcion || d.nombre,
      fecha: d.fecha_diagnostico
    })),
    medicamentos_prescritos: prescripciones.map(p => ({
      medicamento: p.medicamento || p.nombre,
      dosis: p.dosis,
      frecuencia: p.frecuencia,
      duracion: p.duracion
    })),
    recomendaciones_medicas: recomendaciones.map(r => r.descripcion || r.texto)
  },

  // Análisis de riesgo cardiovascular
  analisis_riesgo: {
    nivel_riesgo: riesgoCardiovascular.nivel_riesgo || 'MODERADO',
    probabilidad_riesgo: riesgoCardiovascular.probabilidad_riesgo || 0.3,
    factores_riesgo: factoresInfluyentes.factores_riesgo || [],
    cluster_asignado: priorizacion.cluster || 'MODERADO_JOVEN',
    recomendaciones_ia: priorizacion.recomendaciones || []
  },

  // Historial de seguimientos
  contexto_historico: {
    campana: {
      nombre: campanaDatos.nombre,
      objetivo: campanaDatos.objetivo,
      fecha_inicio: campanaDatos.fecha_inicio
    },
    seguimientos_previos: seguimientosAnteriores.map(s => ({
      fecha: s.fecha_programada,
      tipo: s.tipo,
      estado: s.estado,
      respuestas_anteriores: s.respuestas || null,
      resultado: s.resultado_analisis || 'Sin análisis'
    }))
  },

  // Metadata
  fecha_analisis: new Date().toISOString(),
  version_analisis: '1.0'
};

console.log('✅ Datos estructurados para análisis IA');
console.log('📊 Respuestas a analizar:', Object.keys(respuestas).length);
console.log('🎯 Nivel de riesgo:', datosAnalisis.analisis_riesgo.nivel_riesgo);
console.log('📚 Seguimientos anteriores:', seguimientosAnteriores.length);

return datosAnalisis;

