// 🏥 ESTRUCTURAR ANÁLISIS FINAL DE RESPUESTAS
const inputData = $input.all()[0]?.json || {};
const datosOriginales = $node["Procesar_Datos_Analisis"]?.json;

if (!datosOriginales?.paciente_id) {
  throw new Error('Datos del paciente no disponibles');
}

// Extraer respuesta del AI especialista
let respuestaIA = inputData.output || inputData.text || inputData.response || JSON.stringify(inputData);

try {
  // Limpiar y parsear respuesta JSON
  const jsonString = respuestaIA.replace(/```json/g, '').replace(/```/g, '').trim();
  const cleanString = jsonString.startsWith('"') && jsonString.endsWith('"') ? 
                     jsonString.slice(1, -1) : jsonString;

  const analisisJSON = JSON.parse(cleanString);

  if (!analisisJSON?.analisis_integral) {
    throw new Error('Estructura de análisis inválida');
  }

  // ✅ RESULTADO FINAL ESTRUCTURADO
  const resultadoFinal = {
    success: true,
    analisis_id: `analisis_${datosOriginales.seguimiento_id}_${Date.now()}`,
    paciente_id: datosOriginales.paciente_id,
    seguimiento_id: datosOriginales.seguimiento_id,

    // Análisis completo del especialista IA
    analisis_especialista: analisisJSON,

    // Resumen ejecutivo para dashboard
    resumen_ejecutivo: {
      estado_general: analisisJSON.analisis_integral?.resumen_estado || 'Estado evaluado',
      nivel_riesgo: analisisJSON.analisis_integral?.riesgo_actual?.nivel || 'MODERADO',
      adherencia: analisisJSON.analisis_integral?.adherencia_terapeutica?.nivel || 'REGULAR',
      requiere_atencion_urgente: analisisJSON.analisis_integral?.sintomas_alarma?.presente || false,
      recomendaciones_prioritarias: analisisJSON.recomendaciones_especificas\
        ?.filter(r => r.prioridad === 'ALTA')\
        ?.map(r => r.accion) || []
    },

    // Datos para persistencia
    datos_persistencia: {
      fecha_analisis: new Date().toISOString(),
      analisis_completo: JSON.stringify(analisisJSON),
      estado_seguimiento: analisisJSON.analisis_integral?.sintomas_alarma?.presente ? 'REQUIERE_ATENCION' : 'COMPLETADO',
      puntuacion_riesgo: calcularPuntuacionRiesgo(analisisJSON),
      proxima_evaluacion: calcularProximaEvaluacion(analisisJSON)
    },

    // Contexto original para referencia
    contexto_analisis: {
      respuestas_evaluadas: Object.keys(datosOriginales.respuestas_actuales).length,
      factores_riesgo_considerados: datosOriginales.analisis_riesgo.factores_riesgo.length,
      seguimientos_previos: datosOriginales.contexto_historico.seguimientos_previos.length
    },

    metadata: {
      fecha_generacion: new Date().toISOString(),
      tipo: 'analisis_respuestas_especializado',
      version: '1.0',
      confiabilidad: evaluarConfiabilidad(analisisJSON)
    }
  };

  console.log('✅ Análisis especializado completado');
  console.log('🎯 Nivel de riesgo:', resultadoFinal.resumen_ejecutivo.nivel_riesgo);
  console.log('💊 Adherencia:', resultadoFinal.resumen_ejecutivo.adherencia);
  console.log('⚠️ Requiere atención urgente:', resultadoFinal.resumen_ejecutivo.requiere_atencion_urgente);

  return resultadoFinal;

} catch (error) {
  console.error('❌ Error procesando análisis:', error.message);

  // Fallback con análisis básico
  const respuestasCount = Object.keys(datosOriginales.respuestas_actuales).length;
  const nivelRiesgoBase = datosOriginales.analisis_riesgo.nivel_riesgo;

  return {
    success: true,
    analisis_id: `fallback_${datosOriginales.seguimiento_id}_${Date.now()}`,
    paciente_id: datosOriginales.paciente_id,
    seguimiento_id: datosOriginales.seguimiento_id,

    resumen_ejecutivo: {
      estado_general: 'Análisis básico - requiere revisión manual',
      nivel_riesgo: nivelRiesgoBase,
      adherencia: respuestasCount > 0 ? 'EVALUADA' : 'NO_EVALUADA',
      requiere_atencion_urgente: nivelRiesgoBase === 'ALTO',
      recomendaciones_prioritarias: ['Revisión médica manual requerida']
    },

    datos_persistencia: {
      fecha_analisis: new Date().toISOString(),
      analisis_completo: JSON.stringify({ error: error.message, datos_disponibles: !!datosOriginales }),
      estado_seguimiento: 'REQUIERE_REVISION',
      puntuacion_riesgo: 50, // Valor neutro
      proxima_evaluacion: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString() // 7 días
    },

    metadata: {
      fecha_generacion: new Date().toISOString(),
      tipo: 'analisis_fallback',
      error_original: error.message,
      version: '1.0'
    }
  };
}

// Funciones auxiliares
function calcularPuntuacionRiesgo(analisis) {
  const nivelRiesgo = analisis.analisis_integral?.riesgo_actual?.nivel;
  const mapping = { 'BAJO': 25, 'MODERADO': 50, 'ALTO': 75, 'CRITICO': 100 };
  return mapping[nivelRiesgo] || 50;
}

function calcularProximaEvaluacion(analisis) {
  const frecuencia = analisis.plan_seguimiento?.frecuencia_recomendada || 'Cada 2 semanas';
  let dias = 14; // Default

  if (frecuencia.includes('día')) dias = parseInt(frecuencia.match(/\d+/)?.[0]) || 7;
  if (frecuencia.includes('semana')) dias = (parseInt(frecuencia.match(/\d+/)?.[0]) || 2) * 7;

  return new Date(Date.now() + dias * 24 * 60 * 60 * 1000).toISOString();
}

function evaluarConfiabilidad(analisis) {
  let score = 0;
  if (analisis.analisis_integral) score += 30;
  if (analisis.recomendaciones_especificas?.length > 0) score += 30;
  if (analisis.plan_seguimiento) score += 20;
  if (analisis.opciones_diagnosticas?.length > 0) score += 20;

  if (score >= 80) return 'ALTA';
  if (score >= 60) return 'MEDIA';
  return 'BAJA';
}
